    public async Task<TrainingAdministrationOverview> ReadAsync(Guid? actorId,CancellationToken token)
    {
        var client=await clients.CreateAsync();
        var category=await DataverseMetadataResolver.TableAsync(client,"gaia_categoriacapacitacion",token);var cf=CategoryFields.From(category);
        var training=await DataverseMetadataResolver.TableAsync(client,"gaia_capacitacion",token);var tf=TrainingFields.From(training);
        var version=await DataverseMetadataResolver.TableAsync(client,"gaia_versioncapacitacion",token);var vf=VersionFields.From(version);
        var categoryRows=await DataverseJson.ReadAllAsync(client,$"{category.EntitySetName}?$select={cf.Select}&$orderby={cf.Order} asc,{cf.Name} asc",token);
        var categories=categoryRows.Select(row=>MapCategory(row,cf)).ToArray();var categoryNames=categories.ToDictionary(row=>row.Id,row=>row.Name);
        var rows=await DataverseJson.ReadAllAsync(client,$"{training.EntitySetName}?$select={tf.Select}&$orderby={tf.Name} asc",token);
        var versionRows=await DataverseJson.ReadAllAsync(client,$"{version.EntitySetName}?$select={vf.Select}&$orderby=createdon desc",token);
        var directoryUnits=await directory.ListOrganizationUnitsAsync(token);var people=await directory.ListPeopleAsync(null,null,false,1,500,token);
        var units=directoryUnits.OrderBy(x=>x.Code,StringComparer.OrdinalIgnoreCase).Select(x=>new TrainingReferenceItem(x.Id,x.Code,x.Name,x.ParentId,null,x.Level)).ToArray();var responsibles=people.Items.OrderBy(x=>x.FullName,StringComparer.OrdinalIgnoreCase).Select(x=>new TrainingReferenceItem(x.Id,"",x.FullName,null,x.OrganizationUnitId,0)).ToArray();
        var unitNames=units.ToDictionary(row=>row.Id,row=>row.Name);var responsibleNames=responsibles.ToDictionary(row=>row.Id,row=>row.Name);
        var items=rows.Select(row=>MapTraining(row,tf,categoryNames,unitNames,responsibleNames)).ToArray();
        var trainingNames=items.ToDictionary(row=>row.Id,row=>row.Name);var versions=versionRows.Select(row=>MapVersion(row,vf,trainingNames)).ToArray();
        return new(categories.Count(x=>x.IsActive),items.Length,versions.Count(x=>x.IsActive),categories,items,versions,units,responsibles,actorId.HasValue?responsibles.FirstOrDefault(x=>x.Id==actorId.Value)?.UnitId:null);
    }

    public async Task<Guid> SaveCategoryAsync(Guid? id,SaveTrainingCategory value,CancellationToken token)
    {
        RequireName(value.Name,150);if(value.Order<0)throw new ArgumentException("El orden no puede ser negativo.");
        var color=Clean(value.Color)?.ToUpperInvariant();if(color is not null&&!Regex.IsMatch(color,"^#[0-9A-F]{6}$"))throw new ArgumentException("El color debe tener formato hexadecimal, por ejemplo #286B78.");
        var client=await clients.CreateAsync();var table=await DataverseMetadataResolver.TableAsync(client,"gaia_categoriacapacitacion",token);var f=CategoryFields.From(table);var code=await UniqueCode(client,table,f.Code,Slug(value.Name),id,token);
        return await Write(client,table,id,new(){{f.Name,value.Name.Trim()},{f.Code,code},{f.Description,Clean(value.Description)},{f.Color,color},{f.Icon,Clean(value.Icon)},{f.Order,table.EncodedIntegerValue("gaia_Orden",value.Order)},{"statecode",value.IsActive?0:1}},token);
    }

    public async Task<Guid> SaveTrainingAsync(Guid? id,SaveTraining value,CancellationToken token)
    {
        RequireName(value.Name,200);if(value.CategoryId==Guid.Empty||value.UnitId==Guid.Empty||value.ResponsibleId==Guid.Empty)throw new ArgumentException("Categoría, unidad responsable y responsable funcional son obligatorios.");
