        var category=await DataverseMetadataResolver.TableAsync(client,"gaia_categoriacapacitacion",token);var unit=await DataverseMetadataResolver.TableAsync(client,"gaia_organizacion",token);var responsible=await DataverseMetadataResolver.TableAsync(client,"gaia_terceros",token);
