        var number=id.HasValue?null:await NextVersion(client,table,f,value.TrainingId,token);var payload=new Dictionary<string,object?>{{f.PublicTitle,value.PublicTitle.Trim()},{f.Summary,Clean(value.Summary)},{f.Objective,Clean(value.Objective)},{f.AvailableFrom,value.AvailableFrom},{f.AvailableUntil,value.AvailableUntil},{f.Days,value.DaysToComplete},{f.ExpirationRule,table.EncodedIntegerValue("gaia_ReglaVencimiento",value.ExpirationRule)},{f.DynamicAudience,value.DynamicAudience},{f.Sequential,value.SequentialOrder},{f.Minimum,value.MinimumPercentage},{f.RequiresApproval,value.RequiresApproval},{f.Survey,value.SurveyRequired},{f.AllowExpired,value.AllowExpired},{f.CompletionMessage,Clean(value.CompletionMessage)},{"statecode",0}};
        if(!id.HasValue){payload[f.Name]=$"{value.PublicTitle.Trim()} · v{number}";payload[f.Number]=number;payload[f.Status]=table.EncodedIntegerValue("gaia_Estado",299540000);payload[f.TrainingNav+"@odata.bind"]=$"/{training.EntitySetName}({value.TrainingId:D})";payload[f.CreatedByNav+"@odata.bind"]=$"/{third.EntitySetName}({actorId:D})";if(source.HasValue){payload[f.DynamicAudience]=Boolean(source.Value,f.DynamicAudience);payload[f.Sequential]=Boolean(source.Value,f.Sequential);payload[f.Minimum]=Decimal(source.Value,f.Minimum);payload[f.RequiresApproval]=Boolean(source.Value,f.RequiresApproval);payload[f.Survey]=Boolean(source.Value,f.Survey);payload[f.AllowExpired]=Boolean(source.Value,f.AllowExpired);}}
        return await Write(client,table,id,payload,token);
    }

